<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Middleware\PermissionMiddleware;use App\Services\ReportService;use App\Repositories\CategoryRepository;use App\Repositories\AccountRepository;
final class ReportController { public function index(Request $r):void{PermissionMiddleware::require('reports.view');$f=$r->all();$rows=(new ReportService())->expenses($f,auth_user());$categories=can('categories.view_all')?(new CategoryRepository())->all(['status'=>'active']):(new CategoryRepository())->allForUser((int)auth_user()['id'],true);$accounts=(new AccountRepository())->allVisible(auth_user());View::render('reports/index',compact('rows','f','categories','accounts'));} public function csv(Request $r):void{PermissionMiddleware::require('reports.export');$rows=(new ReportService())->expenses($r->all(),auth_user());header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="expense-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','Amount','Category','Account','User','Description']);foreach($rows as $row)fputcsv($out,[$row['expense_date'],$row['amount'],$row['category'],$row['account'],$row['user_name']??'', $row['description']]);fclose($out);exit;}}
